const axios = require('axios');
const fs = require('fs');
const logStream = fs.createWriteStream('monitor.log', { flags: 'a' });

const log = (message) => {
  const timestamp = new Date().toISOString();
  const logEntry = `[${timestamp}] ${message}\n`;
  process.stdout.write(logEntry);
  logStream.write(logEntry);
};

const checkHealth = async () => {
  try {
    const start = Date.now();
    const response = await axios.get('http://localhost:3000/health');
    const responseTime = Date.now() - start;

    if (response.data.status === 'ok') {
      log(`SUCCESS: Health check OK - Response time: ${responseTime}ms`);
    } else {
      log(`WARNING: Unexpected health status: ${response.data.status}`);
    }
  } catch (error) {
    log(`ERROR: Health check failed - ${error.message}`);
  }
};

// Run health check every 10 seconds
setInterval(checkHealth, 10000);

// Run immediately on start
checkHealth();

